var assembly = typeof(Program).Assembly;
Console.WriteLine(assembly.FullName);
foreach (var type in assembly.GetExportedTypes())
    Console.WriteLine(type.FullName);

public sealed class PluginLoadContext(string pluginPath) : AssemblyLoadContext(isCollectible: true)
{
    protected override Assembly? Load(AssemblyName name)
    {
        var path = Path.Combine(pluginPath, name.Name + ".dll");
        return File.Exists(path) ? LoadFromAssemblyPath(path) : null;
    }
}

// Load, use, then unload:
var ctx = new PluginLoadContext(pluginDir);
var asm = ctx.LoadFromAssemblyName(new AssemblyName("MyPlugin"));
// ... invoke plugin ...
ctx.Unload();
